function validate([weight]) {
  if (!Array.isArray(weight) || weight.length < 1 || weight.length > 1000) return 'weight needs 1 to 1000 apples.';
  if (weight.some(w => !Number.isInteger(w) || w < 1 || w > 1000)) return 'Each weight is a whole number from 1 to 1000.';
  return null;
}

