function maxNumberOfApples(weight) {
  const capacity = 5000;
  weight.sort((a, b) => a - b);
  let total = 0;
  let count = 0;
  for (const w of weight) {
    if (total + w > capacity) {
      break;
    }
    total += w;
    count++;
  }
  return count;
}

