function maxNumberOfApples(weight) {
  // 0/1 knapsack: best[s] is the most apples whose weights sum to exactly s.
  const best = new Array(5001).fill(-1);
  best[0] = 0;
  for (const w of weight) {
    for (let s = 5000; s >= w; s--) {
      if (best[s - w] >= 0 && best[s - w] + 1 > best[s]) best[s] = best[s - w] + 1;
    }
  }
  return Math.max(...best);
}

