function generate(rand, size) {
  const pick = (n) => Math.floor(rand() * n);
  if (size === 'large') {
    const cap = rand() < 0.5 ? 1000 : 10 + pick(200);
    return [Array.from({ length: 1000 }, () => 1 + pick(cap))];
  }
  const n = 1 + pick(12);
  const style = pick(3);
  const weight = Array.from({ length: n }, () => {
    if (style === 0) return 1 + pick(1000);
    if (style === 1) return 600 + pick(401);
    return [1, 500, 999, 1000][pick(4)];
  });
  return [weight];
}
